    inventoryAutomation.abilityFree = function(argument)
        if type(argument) ~= "table" then
            return false
        elseif type(argument.equipped) ~= "table" then
            return false
        elseif type(argument.name) ~= "string" then
            return false
        elseif tonumber(argument.levelReq) == nil then
