        if inventoryAutomation.isKept(argument.name, argument.rarity) then
            return false
        end
        local value2, value3 = tonumber(argument.levelReq), tonumber(config.sellKeepLevel) or 0
        if value3 > 0 then
            if value2 then
                if value2 >= value3 then
                    return false
                end
            end
        end
        return true
    end
