    walls.mapWalls = function()
        local dungeonName = parent:FindFirstChild("dungeonName")
        if dungeonName then
            if dungeonName:IsA("StringValue") then
                if not (parent:FindFirstChild("dungeon")) then
                    if not (dungeonName.Value == "Gilded Skies") then
                        return nil
                    end
                end
            else
                return nil
            end
        else
            return nil
        end
        if dungeonName.Value == "Gilded Skies" then
            if game.PlaceId ~= 101088859550383 then
                if config.gsWallsFit ~= false then
                    if not (walls.gsFits()) then
                        return nil
                    end
                end
            end
        end
        return sharedValue5[dungeonName.Value], dungeonName.Value
    end
    walls.gsFits = function()
        if walls.gsFitOk then
            return true
        end
        local value = os.clock()
        if walls.gsFitAt then
            if value - walls.gsFitAt < 2 then
                return false
            end
        end
        walls.gsFitAt = value
        value = getService("Players").LocalPlayer.Character
        local value2 = value and (value:FindFirstChild("HumanoidRootPart"))
        if not value2 then
            return false
        end
        value = value2.Position
        for index, entry in ipairs(sharedValue5["Gilded Skies"] or {}) do
            local value3, value4, value5 = value.X - entry[1], value.Y - entry[2], value.Z - entry[3]
            local value6, value7, value8 =
                value3 * entry[4] + value4 * entry[7] + value5 * entry[10],
                value3 * entry[5] + value4 * entry[8] + value5 * entry[11],
                value3 * entry[6] + value4 * entry[9] + value5 * entry[12]
            if math.abs(value6) <= entry[13] / 2 + 1 then
                if math.abs(value8) <= entry[15] / 2 + 1 then
                    if value7 >= -entry[14] / 2 - 1 then
                        if value7 <= entry[14] / 2 + 8 then
                            walls.gsFitOk = true
                            return true
                        end
                    end
                end
            end
        end
        if not walls.gsFitSaid then
            walls.gsFitSaid = true
            context.log(
                "Walls",
                ("Gilded Skies: not on the wall file's map at (%.0f, %.0f, %.0f) - the game's map stays"):format(
                    value.X,
                    value.Y,
                    value.Z
                )
            )
        end
        return false
    end
    walls.inWallsMap = function()
        return walls.mapWalls() ~= nil
    end
